<?php require dirname(__DIR__).'/app/bootstrap.php';require_admin();$statuses=['pending','confirmed','processing','shipped','delivered','cancelled'];$status=(string)($_GET['status']??'');$search=trim((string)($_GET['search']??''));$where=[];$params=[];if(in_array($status,$statuses,true)){$where[]='status=?';$params[]=$status;}if($search!==''){$where[]='(reference LIKE ? OR customer_name LIKE ? OR phone LIKE ?)';array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}$condition=$where?' WHERE '.implode(' AND ',$where):'';$page=max(1,(int)($_GET['page']??1));$total=(int)query('SELECT COUNT(*) FROM orders'.$condition,$params)->fetchColumn();$orders=query('SELECT * FROM orders'.$condition.' ORDER BY id DESC LIMIT 30 OFFSET '.(($page-1)*30),$params)->fetchAll();$stats=query("SELECT COUNT(*) AS total,SUM(status='pending') AS pending,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total ELSE 0 END),0) AS revenue FROM orders")->fetch();render_header('Orders',true); ?>
<main class="page admin-page"><div class="section-head"><div><p class="eyebrow">STORE OVERVIEW</p><h1>Orders.</h1></div><form method="post" action="<?=url('admin/export.php')?>"><?=csrf_input()?><button class="button outline">EXPORT ORDERS CSV ↓</button></form></div><div class="stats"><div><span>Total orders</span><strong><?=h($stats['total'])?></strong></div><div><span>Pending review</span><strong><?=h($stats['pending']??0)?></strong></div><div><span>Paid order value</span><strong><?=money($stats['revenue'])?></strong></div></div>
<form method="get" class="filters"><label>Search<input name="search" value="<?=h($search)?>" placeholder="Reference, customer or phone"></label><label>Status<select name="status"><option value="">All orders</option><?php foreach($statuses as $s):?><option <?=$s===$status?'selected':''?> value="<?=$s?>"><?=ucfirst($s)?></option><?php endforeach ?></select></label><button class="button dark">FILTER</button></form><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Amount</th><th>Status</th><th>Payment</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="<?=url('admin/order.php?id='.$o['id'])?>"><?=h($o['reference'])?> ↗</a></td><td><?=h($o['customer_name'])?><br><small><?=h($o['phone'])?></small></td><td><?=money($o['total']??$o['subtotal'])?><?=$o['total']===null?' + delivery':''?></td><td><span class="badge"><?=h($o['status'])?></span></td><td><?=h($o['payment_status'])?></td><td><?=h($o['created_at'])?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders):?><p class="empty">No orders yet. New checkout requests will appear here.</p><?php endif ?><div class="pagination"><?php if($page>1):?><a href="?<?=h(http_build_query(['status'=>$status,'search'=>$search,'page'=>$page-1]))?>">← Previous</a><?php endif ?><span>Page <?=$page?> · <?=$total?> orders</span><?php if($page*30<$total):?><a href="?<?=h(http_build_query(['status'=>$status,'search'=>$search,'page'=>$page+1]))?>">Next →</a><?php endif ?></div></main><?php render_footer(); ?>
